B.bkA=s(["Proje i\xe7in s\xf6zle\u015fme \u015fablonu nas\u0131l olu\u015ftururum?","Firma bilgilerini s\xf6zle\u015fmeye nas\u0131l eklerim?","PDF olu\u015fturup veliye nas\u0131l g\xf6nderirim?"],t.s)
B.bfY=s(["Mahalle bazl\u0131 fiyat nas\u0131l tan\u0131mlar\u0131m?","Km bazl\u0131 fiyat hesaplama nas\u0131l \xe7al\u0131\u015f\u0131r?","Veli adres girince fiyat otomatik \xe7\u0131km\u0131yor, neden?"],t.s)
B.bjn=s(["Yeni proje nas\u0131l olu\u015ftururum?","Farkl\u0131 okul i\xe7in ayr\u0131 proje mi a\xe7mal\u0131y\u0131m?","Projeye s\xf6zle\u015fme \u015fablonu nas\u0131l atar\u0131m?"],t.s)
B.bhA=s(["Excel raporu nas\u0131l al\u0131r\u0131m?","Devams\u0131zl\u0131k raporunu nas\u0131l g\xf6r\xfcr\xfcm?","\u015eof\xf6r listesini nas\u0131l kopyalar\u0131m?"],t.s)
B.beZ=s(["\u0130mzalanan s\xf6zle\u015fme neden silinemiyor?","S\xf6zle\u015fmeyi ar\u015five nas\u0131l kald\u0131r\u0131r\u0131m?","Proje dosyalar\u0131na nas\u0131l eri\u015firim?"],t.s)
B.bgY=s(["Servisi nas\u0131l ba\u015flat\u0131r\u0131m?","\xd6\u011frenci bindi bilgisini nas\u0131l kaydederim?","Navigasyonu nas\u0131l a\xe7ar\u0131m?"],t.s)
B.bic=s(["\xc7ocu\u011fumun servisini nas\u0131l takip ederim?","Devams\u0131zl\u0131k bildirimi nas\u0131l g\xf6nderirim?","\u015eof\xf6rle nas\u0131l ileti\u015fim kurar\u0131m?"],t.s)
B.bfb=s(["Sisteme nereden ba\u015flamal\u0131y\u0131m?","Proje se\xe7imi neden \xf6nemli?","\u0130statistik kartlar\u0131 ne anlama geliyor?"],t.s)
