B.bPN={"Ana Ekran":0,Servisler:1,Kayitlar:2,Sozlesmeler:3,Rotalar:4,Harita:5,Raporlar:6,Ayarlar:7,Fiyatlandirma:8,"Sofor Paneli":9,"Veli Paneli":10,Projeler:11,Arsiv:12,Genel:13}
B.byX=new A.aV(B.aV,["bilgi","Ana Ekran Nedir?","T\xfcm servis operasyonunuzun \xf6zet g\xf6r\xfcn\xfcm\xfcd\xfcr. Toplam \u015fof\xf6r, \xf6\u011frenci, aktif servis ve bekleyen devams\u0131zl\u0131k say\u0131lar\u0131n\u0131 buradan g\xf6rebilirsiniz."],t.l)
B.byZ=new A.aV(B.aV,["adim","\u0130statistik Kartlar\u0131",'\xdcstteki kartlara t\u0131klayarak o b\xf6l\xfcme h\u0131zl\u0131ca ge\xe7ebilirsiniz. \xd6rne\u011fin "Servisler" kart\u0131na t\u0131klay\u0131nca servis y\xf6netim ekran\u0131 a\xe7\u0131l\u0131r.'],t.l)
B.bzM=new A.aV(B.aV,["adim","Canl\u0131 Harita",'Harita b\xf6l\xfcm\xfcnde \u015fof\xf6rlerin anl\u0131k konumlar\u0131n\u0131 g\xf6rebilirsiniz. "Tam Ekran" butonuyla haritay\u0131 b\xfcy\xfctebilirsiniz.'],t.l)
B.bzA=new A.aV(B.aV,["ipucu","Proje Se\xe7imi","Sol \xfcstteki proje se\xe7iciden aktif projeyi de\u011fi\u015ftirebilirsiniz. Her proje kendi \xf6\u011frenci, \u015fof\xf6r ve servis listesine sahiptir."],t.l)
B.bz1=new A.aV(B.aV,["uyari","Bekleyen Devams\u0131zl\u0131klar","Ana sayfada bekleyen devams\u0131zl\u0131k say\u0131s\u0131 k\u0131rm\u0131z\u0131 g\xf6steriliyorsa velilerin g\xf6nderdi\u011fi devams\u0131zl\u0131k bildirimleri var demektir. Hemen kontrol edin."],t.l)
B.bh7=s([B.byX,B.byZ,B.bzM,B.bzA,B.bz1],t.SN)
B.bzh=new A.aV(B.aV,["bilgi","Servis Nedir?",'"1 Servis = 1 \u015eof\xf6r = 1 Ara\xe7" mant\u0131\u011f\u0131yla \xe7al\u0131\u015f\u0131r. Her servis sabah ve ak\u015fam rotas\u0131n\u0131 y\xf6netir. Ak\u015fam rotas\u0131 sabah\u0131n otomatik tersidir.'],t.l)
B.bzJ=new A.aV(B.aV,["adim","Servis Ekle",'Sa\u011f \xfcstteki "Servis Ekle" butonuna bas\u0131n. \u015eof\xf6r ad\u0131, telefon, ara\xe7 plakas\u0131 ve kapasiteyi girin. Kaydetti\u011finizde \u015fof\xf6r hesab\u0131 ve ara\xe7 kayd\u0131 otomatik olu\u015fur.'],t.l)
B.bzp=new A.aV(B.aV,["adim","\u015eof\xf6r Giri\u015fi",'Kaydedilen \u015fof\xf6r, "Kullan\u0131c\u0131 Ad\u0131" ve "Ge\xe7ici \u015eifre" ile uygulamaya giri\u015f yapabilir. \u0130lk giri\u015fte \u015fifresini de\u011fi\u015ftirmesi gerekir.'],t.l)
B.bz7=new A.aV(B.aV,["ipucu","Belgeler","TC Kimlik, Ehliyet S\u0131n\u0131f\u0131, SRC Belgesi ve Psikoteknik Tarihi form alanlar\u0131na girerek kaydedebilirsiniz. Bu bilgiler \u015fof\xf6r profilinde g\xf6r\xfcn\xfcr."],t.l)
B.bzD=new A.aV(B.aV,["uyari","Pasif Yapma",'\u015eof\xf6r\xfc silmek yerine "Pasif Yap" butonunu kullan\u0131n. Bu \u015fekilde ge\xe7mi\u015f servis kay\u0131tlar\u0131 korunur, \u015fof\xf6r uygulamaya giremez hale gelir.'],t.l)
B.blp=s([B.bzh,B.bzJ,B.bzp,B.bz7,B.bzD],t.SN)
B.bzL=new A.aV(B.aV,["bilgi","Kay\u0131tlar Nedir?","\xd6\u011frenci ve veli bilgilerinin merkezi y\xf6netim ekran\u0131d\u0131r. S\xf6zle\u015fme durumunu, atanan servisi ve ayl\u0131k \xfccreti buradan g\xf6rebilirsiniz."],t.l)
B.bzi=new A.aV(B.aV,["adim","Kay\u0131t Ekle",'"Kay\u0131t Ekle" butonuna bas\u0131n. Y\xfcz y\xfcze kay\u0131t formunda \xf6\u011frenci ve veli bilgilerini girin. Adres girince sistem fiyat\u0131 otomatik hesaplar.'],t.l)
B.bzC=new A.aV(B.aV,["adim","Durum Filtreleme",'Dropdown men\xfcden "Bekliyor", "Onayl\u0131" veya "\u0130mzal\u0131" se\xe7erek kay\u0131tlar\u0131 filtreleyebilirsiniz.'],t.l)
B.bzo=new A.aV(B.aV,["ipucu","Veli Hesab\u0131","\xd6\u011frenci kaydedildi\u011finde veli i\xe7in otomatik kullan\u0131c\u0131 hesab\u0131 olu\u015fturulur. Telefon numaras\u0131 kullan\u0131c\u0131 ad\u0131, sistem rastgele \u015fifre \xfcretir."],t.l)
B.bz9=new A.aV(B.aV,["uyari","Servise Atama",'\xd6\u011frenciyi servise atamak i\xe7in \xf6\u011frenci detay\u0131ndan "Servis" alan\u0131n\u0131 g\xfcncelleyin. Atama yap\u0131lmadan \u015fof\xf6r \xf6\u011frenciyi g\xf6remez.'],t.l)
B.bfJ=s([B.bzL,B.bzi,B.bzC,B.bzo,B.bz9],t.SN)
B.bzf=new A.aV(B.aV,["bilgi","S\xf6zle\u015fme Sistemi","Her firma kendi s\xf6zle\u015fme \u015fablonlar\u0131n\u0131 olu\u015fturabilir. Farkl\u0131 projeler i\xe7in farkl\u0131 \u015fablonlar kullan\u0131labilir."],t.l)
B.bzu=new A.aV(B.aV,["adim","\u015eablon Olu\u015ftur",'"Yeni \u015eablon" butonuna bas\u0131n, \u015fablon ad\u0131n\u0131 girin. Sistem otomatik olarak zorunlu maddeleri (KVKK, Emniyet Kemeri) ekler.'],t.l)
B.byU=new A.aV(B.aV,["adim","Madde Y\xf6netimi",'"Haz\u0131r Maddeler" sekmesinde istedi\u011finiz maddeleri a\xe7\u0131p kapatabilirsiniz. Zorunlu maddeler (k\u0131rm\u0131z\u0131 etiketli) kapat\u0131lamaz.'],t.l)
B.bzr=new A.aV(B.aV,["adim","Firma Bilgileri",'"Firma Bilgileri" sekmesinde firma ad\u0131, yetkili, adres ve vergi bilgilerini girin. Bu bilgiler PDF s\xf6zle\u015fmede otomatik g\xf6r\xfcn\xfcr.'],t.l)
B.bzq=new A.aV(B.aV,["adim","PDF Olu\u015ftur",'"PDF & G\xf6nder" sekmesinden PDF olu\u015fturabilir, WhatsApp ile payla\u015fabilir veya metni kopyalayabilirsiniz.'],t.l)
B.byM=new A.aV(B.aV,["ipucu","Proje Bazl\u0131 \u015eablon","Her projeye farkl\u0131 \u015fablon atayabilirsiniz. Projeler \u2192 ilgili proje \u2192 S\xf6zle\u015fme sekmesinden \u015fablon se\xe7in."],t.l)
B.bhG=s([B.bzf,B.bzu,B.byU,B.bzr,B.bzq,B.byM],t.SN)
B.bzl=new A.aV(B.aV,["bilgi","Rota Sistemi","3 sekme: Rotalar (\u015fof\xf6r bazl\u0131), Atamas\u0131zlar (servise atanmam\u0131\u015f \xf6\u011frenciler) ve Servisler (proje bazl\u0131 servisler)."],t.l)
B.bzI=new A.aV(B.aV,["adim","Sabah / Ak\u015fam Ayr\u0131m\u0131","Her \u015fof\xf6r\xfcn alt\u0131nda sabah ve ak\u015fam g\xfczergah\u0131 ayr\u0131 g\xf6sterilir. Ak\u015fam rotas\u0131 sabah\u0131n otomatik tersidir \u2014 Ev\u2192Okul, Okul\u2192Ev."],t.l)
B.byT=new A.aV(B.aV,["adim","Filtreler","\xdcstteki Sabah/Ak\u015fam/\xd6\u011fle butonlar\u0131na t\u0131klayarak sadece o tipteki rotalar\u0131 g\xf6rebilirsiniz."],t.l)
B.bzz=new A.aV(B.aV,["uyari","Atamas\u0131z \xd6\u011frenciler",'"Atamas\u0131zlar" sekmesinde servise atanmam\u0131\u015f \xf6\u011frenciler g\xf6r\xfcn\xfcr. Bu \xf6\u011frencileri bir servise atayana kadar \u015fof\xf6r g\xf6remez.'],t.l)
B.bzd=new A.aV(B.aV,["ipucu","Haritada G\xf6ster","\xd6\u011frenci adresinin yan\u0131ndaki harita ikonuna t\u0131klayarak konumu Google Maps'ta g\xf6rebilirsiniz."],t.l)
B.bhR=s([B.bzl,B.bzI,B.byT,B.bzz,B.bzd],t.SN)
B.bzj=new A.aV(B.aV,["bilgi","Canl\u0131 Takip Haritas\u0131","\u015eof\xf6rlerin anl\u0131k GPS konumlar\u0131n\u0131 haritada g\xf6rebilirsiniz. \u015eof\xf6r uygulamada aktif servis ba\u015flatt\u0131\u011f\u0131nda konumu otomatik g\xfcncellenir."],t.l)
B.bzt=new A.aV(B.aV,["adim","\u015eof\xf6r \u0130konu","Haritadaki ara\xe7 ikonuna t\u0131klay\u0131nca \u015fof\xf6r ad\u0131, plaka ve son g\xfcncelleme zaman\u0131 g\xf6r\xfcn\xfcr."],t.l)
B.bzx=new A.aV(B.aV,["adim","\xd6\u011frenci Duraklar\u0131","\xd6\u011frenci ikonlar\u0131na t\u0131klay\u0131nca o \xf6\u011frencinin ad\u0131 ve bindi/binmedi durumu g\xf6r\xfcn\xfcr."],t.l)
B.bzn=new A.aV(B.aV,["ipucu","Otomatik Takip","Harita 30 saniyede bir otomatik g\xfcncellenir. Manuel yenilemek i\xe7in sa\u011f \xfcstteki yenile butonunu kullan\u0131n."],t.l)
B.byN=new A.aV(B.aV,["uyari","Konum Kapal\u0131ysa","\u015eof\xf6r\xfcn konumu g\xf6z\xfckm\xfcyorsa uygulamada konum izni verilmemi\u015f olabilir. \u015eof\xf6re uygulamada konumu a\xe7mas\u0131n\u0131 s\xf6yleyin."],t.l)
B.b1f=s([B.bzj,B.bzt,B.bzx,B.bzn,B.byN],t.SN)
B.byK=new A.aV(B.aV,["bilgi","Raporlar Ekran\u0131","\xd6\u011frenci say\u0131lar\u0131, \u015fof\xf6r durumlar\u0131, devams\u0131zl\u0131k istatistikleri ve gelir \xf6zetini bu ekranda g\xf6rebilirsiniz."],t.l)
B.bzy=new A.aV(B.aV,["adim","Excel Aktar",'"Excel Aktar" butonuna bas\u0131nca \xf6\u011frenci ve \u015fof\xf6r listesi Excel format\u0131nda haz\u0131rlan\u0131r.'],t.l)
B.byY=new A.aV(B.aV,["adim","Metin Kopyala","\xd6\u011frenci Listesi, \u015eof\xf6r Listesi, Devams\u0131zl\u0131k Raporu ve Genel \xd6zet butonlar\u0131 bilgileri panoya kopyalar. WhatsApp'a yap\u0131\u015ft\u0131rabilirsiniz."],t.l)
B.bzG=new A.aV(B.aV,["ipucu","Devams\u0131zl\u0131k Raporu","Son 30 g\xfcnl\xfck devams\u0131zl\u0131klar listelenir. Velinin g\xf6nderdi\u011fi bildirimler burada g\xf6r\xfcn\xfcr."],t.l)
B.bfw=s([B.byK,B.bzy,B.byY,B.bzG],t.SN)
B.bzF=new A.aV(B.aV,["bilgi","Ayarlar","Firma profili, bildirim ayarlar\u0131, kullan\u0131c\u0131 y\xf6netimi ve sistem yap\u0131land\u0131rmas\u0131n\u0131 buradan yapabilirsiniz."],t.l)
B.bz2=new A.aV(B.aV,["adim","Firma Profili","Firma ad\u0131, logo, adres ve ileti\u015fim bilgilerini g\xfcncelleyin. Bu bilgiler s\xf6zle\u015fme PDF'lerinde ve kay\u0131t formlar\u0131nda otomatik kullan\u0131l\u0131r."],t.l)
B.bza=new A.aV(B.aV,["adim","Kullan\u0131c\u0131 Y\xf6netimi","Y\xf6netici, \u015fof\xf6r ve veli hesaplar\u0131n\u0131 buradan y\xf6netebilirsiniz. Hesap ask\u0131ya alma ve silme i\u015flemleri burada yap\u0131l\u0131r."],t.l)
B.bze=new A.aV(B.aV,["ipucu","Bildirimler","Devams\u0131zl\u0131k bildirimi, \xf6\u011frenci bindi/indi ve servis ba\u015flad\u0131 bildirimlerini a\xe7\u0131p kapatabilirsiniz."],t.l)
B.bhV=s([B.bzF,B.bz2,B.bza,B.bze],t.SN)
B.byW=new A.aV(B.aV,["bilgi","Fiyat Sistemi","\xdc\xe7 farkl\u0131 fiyatland\u0131rma y\xf6ntemi: Mahalle bazl\u0131, \u0130l\xe7e bazl\u0131 ve Kilometre bazl\u0131. Veli adresini girince sistem otomatik fiyat hesaplar."],t.l)
B.bzE=new A.aV(B.aV,["adim","Mahalle / \u0130l\xe7e Bazl\u0131",'"Fiyat Ekle" sekmesinde il\xe7e ve mahalle se\xe7ip fiyat girin. Veli o mahalleden kay\u0131t yapt\u0131r\u0131nca bu fiyat otomatik atan\u0131r.'],t.l)
B.byI=new A.aV(B.aV,["adim","Km Bazl\u0131 Fiyat",'"Km Bazl\u0131" sekmesinde iki y\xf6ntem var: Kademe (0-5km: 1500 TL) veya Birim fiyat (Baz + km\xd7fiyat form\xfcl\xfc).'],t.l)
B.bzv=new A.aV(B.aV,["ipucu","\xd6ncelik S\u0131ras\u0131","Sistem \xf6nce mahalleye bakar, bulamazsa il\xe7eye, sonra km bazl\u0131 hesaplar. En spesifik fiyat ge\xe7erlidir."],t.l)
B.byV=new A.aV(B.aV,["uyari","Fiyat S\xf6zle\u015fmeye \u0130\u015flenir","Hesaplanan fiyat otomatik olarak s\xf6zle\u015fmeye ve PDF'e i\u015flenir. Velinin onaylamas\u0131 gereken \xfccret buradaki fiyatt\u0131r."],t.l)
B.bfk=s([B.byW,B.bzE,B.byI,B.bzv,B.byV],t.SN)
B.bzg=new A.aV(B.aV,["bilgi","\u015eof\xf6r Paneli","Bu ekran \u015fof\xf6rlere \xf6zeldir. \xd6\u011frenci listesi, g\xfczergah, devams\u0131zl\u0131k bildirimi ve canl\u0131 navigasyon \xf6zelliklerini i\xe7erir."],t.l)
B.bzH=new A.aV(B.aV,["adim","Servisi Ba\u015flat",'Turuncu "Servisi Ba\u015flat" butonuna bas\u0131nca konumunuz yay\u0131nlanmaya ba\u015flar ve veliler sizi haritada g\xf6r\xfcr.'],t.l)
B.byR=new A.aV(B.aV,["adim","\xd6\u011frenci Listesi","Her \xf6\u011frencinin yan\u0131ndaki \u2713 butonuna basarak \xf6\u011frencinin bindi bilgisini kaydedin. Veli anl\u0131k bildirim al\u0131r."],t.l)
B.byQ=new A.aV(B.aV,["adim","Devams\u0131zl\u0131k",'\xd6\u011frenci gelmeyecekse "Devams\u0131z" butonuna bas\u0131n. Veliye otomatik bildirim gider.'],t.l)
B.byJ=new A.aV(B.aV,["ipucu","Navigasyon","\xd6\u011frenci adresine t\u0131klayarak Google Maps navigasyonu a\xe7abilirsiniz."],t.l)
B.bz6=new A.aV(B.aV,["uyari","\xc7oklu G\xf6rev","Sabah ve ak\u015fam farkl\u0131 projelerde g\xf6reviniz varsa, giri\u015f yap\u0131nca proje se\xe7im ekran\u0131 a\xe7\u0131l\u0131r. Do\u011fru projeyi se\xe7in."],t.l)
