B.byG=new A.aV(B.aV,["bilgi","Veli Paneli","\xc7ocu\u011funuzun servis durumunu anl\u0131k takip edebilece\u011finiz ekrand\u0131r. Bindi/inmedi bilgisi, \u015fof\xf6r konumu ve devams\u0131zl\u0131k bildirimi burada."],t.l)
B.bz3=new A.aV(B.aV,["adim","Canl\u0131 Konum","Harita b\xf6l\xfcm\xfcnde servis arac\u0131n\u0131n anl\u0131k konumunu g\xf6rebilirsiniz. Ara\xe7 yakla\u015f\u0131nca bildirim al\u0131rs\u0131n\u0131z."],t.l)
B.bz0=new A.aV(B.aV,["adim","Devams\u0131zl\u0131k Bildir",'\xc7ocu\u011funuz servise binmeyecekse sabah servis saatinden en az 30 dakika \xf6nce "Bug\xfcn Gelmiyor" butonuna bas\u0131n.'],t.l)
