B.bzs=new A.aV(B.aV,["adim","Durum Ak\u0131\u015f\u0131","S\xf6zle\u015fmeler \u015fu a\u015famalardan ge\xe7er: Taslak \u2192 Onay Bekliyor \u2192 \u0130mzaland\u0131 \u2192 Ar\u015fivlendi. Her a\u015famada tarih ve i\u015flemi yapan ki\u015fi kaydedilir."],t.l)
B.bzk=new A.aV(B.aV,["adim","Filtreleme","\xdcstteki filtrelerden duruma g\xf6re s\xf6zle\u015fmeleri bulabilirsiniz. Tarih aral\u0131\u011f\u0131 ve proje bazl\u0131 filtreleme de desteklenir."],t.l)
